import{_ as p,a0 as o,w as r,s as d,I as a,x as n,a1 as l,A as i,ao as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何编写和使用自定义的 Shell 函数和函数库 | LCTT x X-CMD","titleTemplate":false,"description":"如何编写和使用自定义的 Shell 函数和函数库 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何编写和使用自定义的 Shell 函数和函数库 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何编写和使用自定义的 Shell 函数和函数库 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20170207 How To Write and Use Custom Shell Functions and Libraries","title":"如何编写和使用自定义的 Shell 函数和函数库","tag":"201703","desc":""},"relativePath":"201703/20170207 How To Write and Use Custom Shell Functions and Libraries.md","filePath":"[post].md"}'),h={name:"201703/20170207 How To Write and Use Custom Shell Functions and Libraries.md"};function u(c,s,g,b,k,m){const e=o("Link");return r(),d("div",null,[s[22]||(s[22]=a("h1",{id:"如何编写和使用自定义的-shell-函数和函数库",tabindex:"-1"},[n("如何编写和使用自定义的 Shell 函数和函数库 "),a("a",{class:"header-anchor",href:"#如何编写和使用自定义的-shell-函数和函数库","aria-label":"Permalink to “如何编写和使用自定义的 Shell 函数和函数库”"},"​")],-1)),a("p",null,[s[1]||(s[1]=n("在 Linux 系统下，Shell 脚本可以在各种不同的情形下帮到我们，例如展示信息，甚至 ",-1)),l(e,{href:"http://www.tecmint.com/using-shell-script-to-automate-linux-system-maintenance-tasks/"},{default:i(()=>[...s[0]||(s[0]=[n("自动执行特定的系统管理任务",-1)])]),_:1}),s[2]||(s[2]=n("，创建简单的命令行工具等等。",-1))]),s[23]||(s[23]=t(`<p>在本指南中，我们将向 Linux 新手展示如何可靠地存储自定义的 shell 脚本，解释如何编写 shell 函数和函数库，以及如何在其它的脚本中使用函数库中的函数。</p><h3 id="shell-脚本要存储在何处" tabindex="-1">Shell 脚本要存储在何处 <a class="header-anchor" href="#shell-脚本要存储在何处" aria-label="Permalink to “Shell 脚本要存储在何处”">​</a></h3><p>为了在执行你自己的脚本时不必输入脚本所在位置的完整或绝对路径，脚本必须被存储在 <code>$PATH</code> 环境变量所定义的路径里的其中一个。</p><p>使用下面的命令可以查看你系统中的 <code>$PATH</code> 环境变量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $PATH</span></span>
<span class="line"><span>/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:/usr/games:/usr/local/games</span></span></code></pre></div><p>通常来说，如果在用户的家目录下存在名为 <code>bin</code> 的目录，你就可以将 shell 脚本存储在那个目录下，因为那个目录会自动地被包含在用户的 <code>$PATH</code> 环境变量中（LCTT 译注：在 Centos 6/7 下是这样的，在 Debian 8 下不是这样的，在 Ubuntu 16.04 下又是这样的)。</p>`,6)),a("p",null,[s[4]||(s[4]=n("因此，在你的主目录下创建 ",-1)),s[5]||(s[5]=a("code",null,"bin",-1)),s[6]||(s[6]=n(" 目录吧（当然这里也可以用来存储 Perl、",-1)),l(e,{href:"http://www.tecmint.com/use-linux-awk-command-to-filter-text-string-in-files/"},{default:i(()=>[...s[3]||(s[3]=[n("Awk",-1)])]),_:1}),s[7]||(s[7]=n(" 或 Python 的脚本，或者其它程序）：",-1))]),s[24]||(s[24]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir ~/bin</span></span></code></pre></div><p>接着，建立一个名为 <code>lib</code>（libraries 的简写）的目录来存放你自己的函数库。你也可以在其中存放其它编程语言的函数库，如 C ，Python 等语言。在 <code>lib</code> 目录下建立另一个名为 <code>sh</code> 的目录，这个目录将被用来存放你的 shell 函数库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir -p ~/lib/sh</span></span></code></pre></div><h3 id="创建你自己的-shell-函数和函数库" tabindex="-1">创建你自己的 Shell 函数和函数库 <a class="header-anchor" href="#创建你自己的-shell-函数和函数库" aria-label="Permalink to “创建你自己的 Shell 函数和函数库”">​</a></h3><p>一个 <code>shell 函数</code> 就是在脚本中能够完成特定任务的一组命令。它们的工作原理与其他编程语言中的过程（LCTT 译注：可能指的是类似 SQL 中的存储过程之类的吧）、子例程、函数类似。</p><p>编写一个函数的语法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>函数名() { 一系列的命令 }</span></span></code></pre></div><p>( LCTT 校注：在函数名前可以加上 <code>function</code> 关键字，但也可省略不写）</p><p>例如，你可以像下面那样在一个脚本中写一个用来显示日期的函数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>showDATE() {date;}</span></span></code></pre></div><p>每当你需要显示日期时，只需调用该函数的函数名即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ showDATE</span></span></code></pre></div><p>简单来说 shell 函数库也是一个 shell 脚本，不过你可以在一个函数库中仅存储其它 shell 脚本中需要调用的函数。</p><p>下面展示的是在我的 <code>~/lib/sh</code> 目录下一个名为 <code>libMYFUNCS.sh</code> 的库函数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash </span></span>
<span class="line"><span>#Function to clearly list directories in PATH </span></span>
<span class="line"><span>showPATH() { </span></span>
<span class="line"><span>oldifs=&quot;$IFS&quot;   #store old internal field separator</span></span>
<span class="line"><span>IFS=:              #specify a new internal field separator</span></span>
<span class="line"><span>for DIR in $PATH ;  do echo $DIR ;  done</span></span>
<span class="line"><span>IFS=&quot;$oldifs&quot;    #restore old internal field separator</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>#Function to show logged user</span></span>
<span class="line"><span>showUSERS() {</span></span>
<span class="line"><span>echo -e “Below are the user logged on the system:\\n”</span></span>
<span class="line"><span>w</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>#Print a user’s details </span></span>
<span class="line"><span>printUSERDETS() {</span></span>
<span class="line"><span>oldifs=&quot;$IFS&quot;    #store old internal field separator</span></span>
<span class="line"><span>IFS=:                 #specify a new internal field separator</span></span>
<span class="line"><span>read -p &quot;Enter user name to be searched:&quot; uname   #read username</span></span>
<span class="line"><span>echo &quot;&quot;</span></span>
<span class="line"><span>#read and store from a here string values into variables using : as  a  field delimiter</span></span>
<span class="line"><span>read -r username pass uid gid comments homedir shell &lt;&lt;&lt; &quot;$(cat /etc/passwd | grep   &quot;^$uname&quot;)&quot;</span></span>
<span class="line"><span>#print out captured values</span></span>
<span class="line"><span>echo  -e &quot;Username is            : $username\\n&quot;</span></span>
<span class="line"><span>echo  -e &quot;User&#39;s ID                 : $uid\\n&quot;</span></span>
<span class="line"><span>echo  -e &quot;User&#39;s GID              : $gid\\n&quot;</span></span>
<span class="line"><span>echo  -e &quot;User&#39;s Comments    : $comments\\n&quot;</span></span>
<span class="line"><span>echo  -e &quot;User&#39;s Home Dir     : $homedir\\n&quot;</span></span>
<span class="line"><span>echo  -e &quot;User&#39;s Shell             : $shell\\n&quot;</span></span>
<span class="line"><span>IFS=&quot;$oldifs&quot;         #store old internal field separator</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>保存文件并且给脚本添加执行权限。</p><h3 id="如何从函数库中调用函数" tabindex="-1">如何从函数库中调用函数 <a class="header-anchor" href="#如何从函数库中调用函数" aria-label="Permalink to “如何从函数库中调用函数”">​</a></h3><p>要使用某个 <code>lib</code> 目录下的函数，首先你需要按照下面的形式 将包含该函数的函数库导入到需要执行的 shell 脚本中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ . /path/to/lib </span></span>
<span class="line"><span>或</span></span>
<span class="line"><span>$ source /path/to/lib</span></span></code></pre></div><p>（LCTT 译注：第一行的 <code>.</code> 和路径间<strong>必须</strong>是有空格的）</p><p>这样你就可以像下面演示的那样，在其它的脚本中使用来自 <code>~/lib/sh/libMYFUNCS.sh</code> 的 <code>printUSERDETS</code> 函数了。</p><p>在下面的脚本中，如果要打印出某个特定用户的详细信息，你不必再一一编写代码，而只需要简单地调用已存在的函数即可。</p><p>创建一个名为 <code>test.sh</code> 的新文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash </span></span>
<span class="line"><span>#include lib</span></span>
<span class="line"><span>.  ~/lib/sh/libMYFUNCS.sh</span></span>
<span class="line"><span>#use function from lib</span></span>
<span class="line"><span>printUSERDETS</span></span>
<span class="line"><span>#exit script</span></span>
<span class="line"><span>exit 0</span></span></code></pre></div><p>保存这个文件，并使得这个脚本可被执行，然后运行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod 755 test.sh</span></span>
<span class="line"><span>$ ./test.sh</span></span></code></pre></div>`,26)),a("p",null,[l(e,{href:"http://www.tecmint.com/wp-content/uploads/2017/02/Write-Shell-Functions.png"},{default:i(()=>[...s[8]||(s[8]=[a("img",{src:"http://www.tecmint.com/wp-content/uploads/2017/02/Write-Shell-Functions.png",alt:"Write Shell Functions"},null,-1)])]),_:1})]),s[25]||(s[25]=a("p",null,[a("em",null,"编写 shell 函数")],-1)),s[26]||(s[26]=a("p",null,"在本文中，我们介绍了在哪里可靠地存储 shell 脚本，如何编写自己的 shell 函数和函数库，以及如何在一个普通的 shell 脚本中从函数库中调用库中的某些函数。",-1)),s[27]||(s[27]=a("p",null,"在之后，我们还会介绍一种相当简单直接的方式来将 Vim 配置为一个编写 Bash 脚本的 IDE（集成开发环境）。在那之前，记得要经常关注我们 ，如果能和我们分享你对这份指南的想法就更好了。",-1)),s[28]||(s[28]=a("hr",null,null,-1)),s[29]||(s[29]=a("p",null,"作者简介：Aaron Kili 是一名 Linux 和 F.O.S.S 爱好者、一名未来的 Linux 系统管理员、web 开发者，目前是一名 TecMint 上的内容创造者，他喜欢计算机相关的工作，并且坚信知识的分享。",-1)),s[30]||(s[30]=a("hr",null,null,-1)),a("p",null,[s[10]||(s[10]=n("via: ",-1)),l(e,{href:"http://www.tecmint.com/write-custom-shell-functions-and-libraries-in-linux/"},{default:i(()=>[...s[9]||(s[9]=[n("http://www.tecmint.com/write-custom-shell-functions-and-libraries-in-linux/",-1)])]),_:1})]),a("p",null,[s[14]||(s[14]=n("作者：",-1)),l(e,{href:"http://www.tecmint.com/author/aaronkili/"},{default:i(()=>[...s[11]||(s[11]=[n("Aaron Kili",-1)])]),_:1}),s[15]||(s[15]=n(" 译者：",-1)),l(e,{href:"https://github.com/wcnnbdk1"},{default:i(()=>[...s[12]||(s[12]=[n("wcnnbdk1",-1)])]),_:1}),s[16]||(s[16]=n(" 校对：",-1)),l(e,{href:"https://github.com/FSSlc"},{default:i(()=>[...s[13]||(s[13]=[n("FSSlc",-1)])]),_:1})]),a("p",null,[s[19]||(s[19]=n("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[17]||(s[17]=[n("LCTT",-1)])]),_:1}),s[20]||(s[20]=n(" 原创编译，",-1)),l(e,{href:"https://linux.cn/"},{default:i(()=>[...s[18]||(s[18]=[n("Linux中国",-1)])]),_:1}),s[21]||(s[21]=n(" 荣誉推出",-1))])])}const S=p(h,[["render",u]]);export{C as __pageData,S as default};
